import { expect, type Page } from '@playwright/test'

export const SHOTS = '/home/hatch/workspace/your_files'

/** Fixtures live in the repo (tests/e2e-05/fixtures/) — regenerated by
 * `npm run make-fixtures`; no /tmp dependency. Resolved via import.meta.url
 * (no node: imports — this project has no @types/node). */
function fixturePath(fixture: string): string {
  return new URL(`../fixtures/${fixture}.json`, import.meta.url).pathname
}

/** Collect page errors; assert none at the end of each test. */
export function trackErrors(page: Page): string[] {
  const errors: string[] = []
  page.on('pageerror', (e) => errors.push(String(e)))
  return errors
}

export function assertNoErrors(errors: string[]) {
  expect(errors, `page errors: ${errors.join(' | ')}`).toEqual([])
}

/** Fresh profile: create a campaign + party through the UI. */
export async function bootstrap(page: Page, name = 'Probe', classes = ['Warrior', 'Cleric', 'Rogue', 'Wizard']) {
  await page.goto('campaign')
  await expect(page.getByRole('button', { name: 'New campaign' }).first()).toBeVisible()
  await page.getByRole('button', { name: 'New campaign' }).first().click()
  await page.getByPlaceholder('Campaign name').fill(name)
  await page.getByRole('button', { name: 'Create campaign' }).click()
  await expect(page).toHaveURL(/\/party\/new/)
  // Class picker: plain class names, no citations (Part B).
  for (const cls of classes) {
    await page.getByRole('button', { name: cls, exact: true }).click()
  }
  await page.getByRole('button', { name: 'Create party' }).click()
  await expect(page).toHaveURL(/\/party/)
}

/** Import a fixture archive through Settings, then open the imported campaign. */
export async function importFixture(page: Page, fixture: string, label: string) {
  await page.goto('settings')
  await expect(page.getByRole('button', { name: 'Import JSON' })).toBeVisible()
  const input = page.locator('input[type="file"]')
  await input.setInputFiles(fixturePath(fixture))
  await expect(page.getByText(`Imported “${label}” as a new campaign.`)).toBeVisible()
  await page.goto('campaign')
  // The open button's accessible name starts with the campaign name; the
  // Duplicate/Delete buttons start with those words instead. The list is
  // newest-first, so the freshest import is the first match.
  const safe = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  await page.getByRole('button', { name: new RegExp(`^${safe} \\(imported\\)`) }).first().click()
  await page.goto('dungeon')
  await expect(page.locator('text=Darkness').or(page.locator('text=Lit by'))).toBeVisible({ timeout: 15000 })
}

export async function engage(page: Page) {
  await expect(page.getByRole('button', { name: 'Engage!' })).toBeVisible()
  await page.getByRole('button', { name: 'Engage!' }).click()
}

export function victoryStamp(page: Page) {
  return page.locator('[role="status"].victory-stamp')
}

/** Click the first glowing (unexplored) exit disc. */
export async function exploreExit(page: Page) {
  const disc = page.locator('circle.cursor-pointer').first()
  await expect(disc).toBeVisible()
  await disc.dispatchEvent('pointerup')
}

/** Attack until the combat is won or the party falls; returns true on win. */
export async function attackUntilWon(page: Page, maxRounds = 40): Promise<boolean> {
  for (let i = 0; i < maxRounds; i++) {
    if (await victoryStamp(page).isVisible().catch(() => false)) return true
    if (await page.getByText('Fallen').first().isVisible().catch(() => false)) return false
    const attack = page.getByRole('button', { name: /^Attack / }).first()
    if (await attack.isVisible().catch(() => false)) {
      await attack.click()
      await page.waitForTimeout(400)
      continue
    }
    const wait = page.getByRole('button', { name: 'Wait for Reactions' })
    if (await wait.isVisible().catch(() => false)) {
      await wait.click()
      await page.waitForTimeout(400)
      continue
    }
    await page.waitForTimeout(500)
  }
  return await victoryStamp(page).isVisible().catch(() => false)
}

/** Assert no rulebook citation is visible anywhere on the page. */
export async function assertNoCitationsVisible(page: Page) {
  const text = (await page.locator('body').innerText()).replace(/\s+/g, ' ')
  expect(text).not.toMatch(/FADEE pp?\./)
}
